type State struct { Count int; Loading bool }
type Intent struct { Kind, Text string }

func reduce(s State, in Intent) State {
    switch in.Kind {
    case "inc":     s.Count++
    case "refresh": s.Loading = true
    case "failed":  s.Loading = false
    }
    return s // unhandled intent: same state value, no copy
}
